#pragma once

#include "DSP/Oscillators/OscillatorBase.h"
#include "DSP/Utilities/Smoothing.h"

namespace omnivy {
namespace dsp {

// -----------------------------------------------------------------------------
// Virtual-Analog oscillator. Produces sine, saw, square, triangle and pulse
// waveforms from a phase accumulator. Each instance owns its phase, so multiple
// oscillators run independently with independent detune/octave/semitone.
//
// The waveforms are generated by direct phase maths (musical, aliasing present
// band-limited reduction is planned via oversampling in a later phase).
// -----------------------------------------------------------------------------
class VAOscillator : public OscillatorBase
{
public:
    VAOscillator();
    ~VAOscillator() override = default;

    void setSampleRate (double sampleRate) override;
    void reset() override;

    void setFrequency (float frequencyHz) override;
    float getFrequency() const override;

    void setWaveform (Waveform waveform) override;
    Waveform getWaveform() const override;

    void setLevel (float level) override;
    float getLevel() const override;
    void setPan (float pan) override;
    float getPan() const override;
    void setActive (bool active) override;
    bool isActive() const override;

    void setOctave (int octave) override;
    void setSemitone (int semitone) override;
    void setDetuneCents (float cents) override;
    void setFineTuneCents (float cents) override;

    void setInitialPhase (float phase) override;
    float getPhase() const override;

    StereoFrame processSample() override;

private:
    float effectiveFrequency() const noexcept;

    float m_frequencyHz = 440.0f;     // base note frequency
    float m_phase = 0.0f;             // 0..1
    float m_phaseIncrement = 0.0f;

    Waveform m_waveform = Waveform::Saw;

    float m_level = 0.7f;
    float m_pan = 0.0f;
    bool  m_active = true;

    int m_octave = 0;
    int m_semitone = 0;
    float m_detuneCents = 0.0f;
    float m_fineTuneCents = 0.0f;
    float m_initialPhase = 0.0f;

    LinearSmoother m_levelSmoother;
};

} // namespace dsp
} // namespace omnivy
